 void RefreshReceipts(string id){receiptList.BeginUpdate();receiptList.Items.Clear();foreach(var r in receiptStore.Records.OrderBy(r=>r.Info.Name,StringComparer.CurrentCulture))receiptList.Items.Add(r);if(id!=null)for(int i=0;i<receiptList.Items.Count;i++)if(((ReceiptRecord)receiptList.Items[i]).Id==id)receiptList.SelectedIndex=i;receiptList.EndUpdate();}
 ReceiptRecord SelectedReceipt(){var r=receiptList.SelectedItem as ReceiptRecord;if(r==null)throw new Exception("请先在左侧选择收款记录。");return r;}
 void EditReceipt(bool edit){var current=edit?SelectedReceipt():null;using(var f=new ReceiptEditor(current==null?null:current.Info)){if(f.ShowDialog(this)!=DialogResult.OK)return;RunChange(edit?"编辑收款记录":"新增收款记录",()=>{string id=receiptStore.Save(f.Result,current==null?null:current.Id);RefreshReceipts(id);});status.Text="收款记录已保存到本地，可重复选用。";}}
 void DeleteReceipt(){var r=SelectedReceipt();if(MessageBox.Show(this,"删除本地记录“"+r.Label+"”？已生成的打款表不会改变。","删除记录",MessageBoxButtons.YesNo,MessageBoxIcon.Question)!=DialogResult.Yes)return;RunChange("删除收款记录",()=>{receiptStore.Delete(r.Id);RefreshReceipts(null);});status.Text="已删除收款记录。";}
 void UseSelectedReceipt(){Require();var r=SelectedReceipt();RunChange("应用收款记录",()=>model.UseReceipt(r.Info,Convert.ToString(paymentTarget.SelectedItem)));payFilter.Apply();UpdateMetrics();status.Text="已将“"+r.Label+"”用于全部任务；收款类型小额、比例1、金额留空。";}
 void OpenLeaderAmount(){Require();if(receiptStore.Records.Count==0)throw new Exception("请先新增并保存团长、达人的收款记录。");Commit();var before=CaptureState();using(var f=new LeaderAmountWindow(model,receiptStore.Records)){if(f.ShowDialog(this)!=DialogResult.OK)return;RecordStep(before,"录入团长打款金额");payFilter.Apply();UpdateMetrics();status.Text="已更新 "+f.Applied+" 个任务，团长与达人金额一致、团长比例留空。";}}
 void SyncAdjustment(){Require();Commit();int n=0;RunChange("同步至调差",()=>{n=model.SyncFixedToAdjustment();adjustFilter.Apply();UpdateMetrics();tabs.SelectedIndex=3;});status.Text="已同步 "+n+" 个任务的一口价至线上成本，未填写任务保留原调差结果。";}
 void UpdateNavigation(){if(tabs==null)return;string[] h={"结算核对工作台","打款信息与收款记录","异常检查中心","结算调差工作台"};string[] sub={"同任务同单价合并日期范围，一口价可同步至调差","本地保存收款记录，可重复选用；团长金额单独录入","把价格变化、日期断档与金额差异集中展示，便于处理","原始差异按任务汇总，一口价同步后替换对应线上成本"};int i=Math.Max(0,tabs.SelectedIndex);heading.Text=h[i];if(syncButton!=null)syncButton.Visible=i==0;subtitle.Text=sub[i];for(int j=0;j<nav.Length;j++){nav[j].BackColor=j==i?Color.FromArgb(36,60,95):Color.FromArgb(18,27,44);nav[j].ForeColor=j==i?Cyan:Color.FromArgb(177,192,215);}}
 void Require(){if(model==null)throw new Exception("请先点击“上传原始明细”，选择结算明细 Excel。");}
 void Commit(){Require();if(committing)return;committing=true;try{if(!checkGrid.EndEdit()||!adjustGrid.EndEdit()||!payGrid.EndEdit()||!warningGrid.EndEdit())throw new Exception("请修正当前金额单元格中的数字。");BindingContext[model.Check.DefaultView].EndCurrentEdit();BindingContext[model.Adjust.DefaultView].EndCurrentEdit();BindingContext[model.Payment.DefaultView].EndCurrentEdit();BindingContext[model.Warnings.DefaultView].EndCurrentEdit();model.Refresh();UpdateMetrics();}finally{committing=false;}}
 void UpdateMetrics(){UpdateAdjustmentTotal();if(model==null)return;metric[0].Text=model.Records.Count.ToString();metric[1].Text=model.Records.Select(r=>r.Task).Distinct().Count()+" / "+model.Check.Rows.Count;metric[2].Text=model.Check.AsEnumerable().Sum(r=>(decimal)r[6]).ToString("N2");metric[3].Text=model.Issues.Count.ToString();}
 void UpdateAdjustmentTotal(){if(adjustTotal==null)return;decimal total=0,visible=0;if(model!=null){total=model.Adjust.AsEnumerable().Where(r=>r.RowState!=DataRowState.Deleted&&!r.IsNull("线上成本")).Sum(r=>Convert.ToDecimal(r["线上成本"]));visible=model.Adjust.DefaultView.Cast<DataRowView>().Where(r=>!r.Row.IsNull("线上成本")).Sum(r=>Convert.ToDecimal(r["线上成本"]));}adjustTotal.Text="调差总金额："+total.ToString("N2")+" 元"+(model!=null&&model.Adjust.DefaultView.Count!=model.Adjust.Rows.Count?"    /    当前显示："+visible.ToString("N2")+" 元":"");}
 void Navigate(int index){if(model==null){if(index!=1)throw new Exception("请先上传原始结算明细。");tabs.SelectedIndex=index;UpdateNavigation();status.Text="可先新增本地收款记录，之后上传明细复用。";return;}Commit();tabs.SelectedIndex=index;UpdateNavigation();status.Text="结算周期 "+model.Period+"  /  转化 "+model.Records.Sum(r=>r.Count)+"  /  调差 "+model.Adjust.Rows.Count+" 条";}
 string ChooseXlsx(){using(var d=new OpenFileDialog{Filter="Excel 工作簿 (*.xlsx)|*.xlsx",CheckFileExists=true})return d.ShowDialog(this)==DialogResult.OK?d.FileName:null;}
 void LoadFile(){string p=ChooseXlsx();if(p==null)return;if(model!=null&&MessageBox.Show(this,"重新上传将替换当前预览和未保存的填写内容。是否继续？","重新上传",MessageBoxButtons.YesNo)==DialogResult.No)return;var read=Xlsx.Read(p);if(read.Count==0)throw new Exception("文件没有工作表。");sheets=read;source=p;busy=true;sheetChoice.Items.Clear();foreach(var s in sheets)sheetChoice.Items.Add(s.Name);int index=read.FindIndex(s=>s.Rows.Take(30).Any(r=>r.Value.Values.Any(c=>Xlsx.Norm(c.Text)=="任务ID")));sheetChoice.SelectedIndex=Math.Max(0,index);busy=false;LoadSelected();}
 static void FindHeader(Sheet s,string required){foreach(var row in s.Rows.Take(30)){if(row.Value.Values.Any(c=>Xlsx.Norm(c.Text)==Xlsx.Norm(required))){s.SetHeader(row.Key);return;}}throw new Exception("找不到表头："+required);}
 void LoadSelected(){if(sheets==null)return;var s=sheets[sheetChoice.SelectedIndex];FindHeader(s,"任务ID");var loaded=Model.Load(s);model=loaded;ResetHistory();checkGrid.DataSource=model.Check;payGrid.DataSource=model.Payment;warningGrid.DataSource=model.Warnings;adjustGrid.DataSource=model.Adjust;
