 Sheet ChooseSheet(List<Sheet> list){if(list.Count==1)return list[0];using(var f=new Form{Text="选择工作表",Size=new Size(390,175),StartPosition=FormStartPosition.CenterParent,Font=Font}){var combo=new ComboBox{Left=20,Top=20,Width=335,DropDownStyle=ComboBoxStyle.DropDownList};combo.Items.AddRange(list.Select(s=>s.Name).ToArray());combo.SelectedIndex=0;var ok=new Button{Text="确定",Left=250,Top=65,DialogResult=DialogResult.OK};f.Controls.Add(combo);f.Controls.Add(ok);f.AcceptButton=ok;return f.ShowDialog(this)==DialogResult.OK?list[combo.SelectedIndex]:null;}}
 string SavePath(string ext,string name){using(var d=new SaveFileDialog{Filter="Excel 工作簿|*.xlsx",FileName=name+".xlsx",OverwritePrompt=true})return d.ShowDialog(this)==DialogResult.OK?d.FileName:null;}
 void Guard(string p){if(String.Equals(Path.GetFullPath(p),Path.GetFullPath(source),StringComparison.OrdinalIgnoreCase))throw new Exception("不能覆盖原始结算明细，请另选文件名。");}
 void OfferOpen(string[] files){SavedFilesPrompt.Show(this,files,path=>System.Diagnostics.Process.Start(new System.Diagnostics.ProcessStartInfo{FileName=path,UseShellExecute=true}));}
 void ExportCurrent(){Require();Commit();int index=tabs.SelectedIndex;if(index==1){model.ValidatePayment();}string p=SavePath("xlsx",model.ReportName(index));if(p==null)return;Guard(p);if(index==0)model.ExportCheck(p);else if(index==1)model.ExportPayment(p);else if(index==2)model.ExportWarnings(p);else model.ExportAdjust(p);status.Text="导出完成  /  "+p;OfferOpen(new[]{p});}
 void ExportAll(){Require();Commit();model.ValidatePayment();using(var d=new FolderBrowserDialog{Description="选择保存位置，将创建一个新的结算结果文件夹"}){if(d.ShowDialog(this)!=DialogResult.OK)return;string folder=Path.Combine(d.SelectedPath,"结算结果_"+model.Period+"_"+DateTime.Now.ToString("HHmmss")+"_"+Guid.NewGuid().ToString("N").Substring(0,4));Directory.CreateDirectory(folder);model.ExportCheck(Path.Combine(folder,model.ReportName(0)+".xlsx"));model.ExportPayment(Path.Combine(folder,model.ReportName(1)+".xlsx"));model.ExportWarnings(Path.Combine(folder,model.ReportName(2)+".xlsx"));model.ExportAdjust(Path.Combine(folder,model.ReportName(3)+".xlsx"));status.Text="全部导出完成  /  "+folder;OfferOpen(Enumerable.Range(0,4).Select(i=>Path.Combine(folder,model.ReportName(i)+".xlsx")).ToArray());}}
}
